          start: 'top 85%',
          toggleActions: 'play none none none',
        },
      });
    } else if (mode === 'text') {
      if ('ontouchstart' in window || navigator.maxTouchPoints > 0) {
        gsap.set(element, { opacity: 0, visibility: 'visible' });
        gsap.to(element, {
          opacity: 1,
          duration: d_duration,
          scrollTrigger: { trigger: element, start: 'top 85%' },
        });
        return;
      }

      document.fonts.ready.then(() => {
        const split = new SplitText(element, {
          type: 'lines',
          linesClass: 'split-line',
        });

        gsap.set(element, { autoAlpha: 1 });
        gsap.set(split.lines, { yPercent: 100, opacity: 0 });

        gsap.to(split.lines, {
          yPercent: 0,
          opacity: 1,
          stagger: d_stagger,
          duration: d_duration,
          delay: d_delay,
          ease: 'power2.out',
          scrollTrigger: { trigger: element, start: 'top 85%' },
        });
      });
    } else if (mode === 'scramble') {
      gsap.set(element, { opacity: 0, visibility: 'visible' });
      gsap.to(element, {
        opacity: 1,
        duration: d_duration,
        delay: d_delay,
        ease: 'power2.out',
        scrambleText: {
          text: element.innerText,
          chars: 'upperCase',
          revealDelay: 0.1,
          speed: 0.3,
        },
        scrollTrigger: { trigger: element, start: 'top 85%' },
      });
    }
  });
});

window.addEventListener('load', function () {
  if (typeof gsap === 'undefined' || typeof ScrollTrigger === 'undefined') {
    console.warn('GSAP or ScrollTrigger missing.');
    return;
  }

  gsap.registerPlugin(ScrollTrigger);

  const dividerLines = document.querySelectorAll('.divider-line');

  dividerLines.forEach((line) => {
    // Get the natural/computed width (could be %, px, etc.)
    const targetWidth = getComputedStyle(line).width;

    // Set to 0 first
    gsap.set(line, {
      width: 0,
      transformOrigin: 'left center',
      visibility: 'visible',
    });

    // Animate back to its original width
    gsap.to(line, {
      width: targetWidth,
      duration: 1,
      ease: 'power2.out',
      scrollTrigger: {
        trigger: line,
        start: 'top 85%',
        toggleActions: 'play none none none',
      },
    });
  });
});
